# Now let me try to create a fully solidified version manually
def solidify_hollow_squares(grid_str, bg_color=3):
    """Fill hollow squares with their border color"""
    lines = grid_str.strip().split('\n')

    # Parse into grid
    grid = []
    for line in lines:
        row = [int(c) for c in line.replace(' ', '')]
        grid.append(row)

    # Find hollow squares using connected components
    from collections import deque

    def find_hollow_square(r_start, c_start, size):
        """Check if position starts a hollow square of given size"""
        if r_start + size > len(grid) or c_start + size > len(grid[0]):
            return False

        color = grid[r_start][c_start]
        if color == bg_color:
            return False

        # Check top and left borders exist
        for i in range(1, size):
            if grid[r_start][c_start+i] == bg_color:
                return False
            if grid[r_start+i][c_start] == bg_color:
                return False

        # Check interior is empty (bg_color)
        for dr in range(1, size):
            for dc in range(1, size):
                if grid[r_start+dr][c_start+dc] != bg_color:
                    return False

        return True

    # For each pixel that could be top-left of a hollow square
    new_grid = [list(row) for row in grid]
    changed = True

    while changed:
        changed = False
        for r in range(len(new_grid)):
            for c in range(len(new_grid[0])):
                if new_grid[r][c] == bg_color:
                    continue

                color = new_grid[r][c]
                # Try different sizes
                for size in range(min(len(new_grid), len(new_grid[0])), 1, -1):
                    if find_hollow_square(r, c, size):
                        # Fill the interior
                        for dr in range(1, size):
                            for dc in range(1, size):
                                new_grid[r+dr][c+dc] = color

                        changed = True
                        break

    return new_grid

